{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE TABLE IF NOT EXISTS neshanka-wh.maplemonk.sku_master ( skucode STRING, name STRING, category STRING, sub_category STRING ); CREATE OR REPLACE TABLE neshanka-wh.maplemonk.neshanka_wh_AMAZON_USA_FACT_ITEMS_INTERMEDIATE AS SELECT \'Custom_Amazon_Seller_Partner_ASP_SG\' AS shop_name, cast(amazon_order_id as string) order_id, cast(amazon_order_id AS string) order_name, NULL AS customer_id, NULL AS phone, NULL AS tags, NULL AS line_item_id, cast(Sku as string ) sku, ASIN AS product_id, cast(Currency as string) Currency, CASE WHEN order_status IN (\'Shipped - Returned to Seller\', \'Shipped - Returning to Seller\', \'Shipped - Rejected by Buyer\', \'Shipped - Damaged\') THEN 1 ELSE 0 END AS is_refund, cast(UPPER(ship_city) as string) AS city, cast(UPPER(ship_state) as string) AS state, cast(ship_postal_code as string) AS pincode, upper(cast(product_name as string)) AS product_name, NULL AS category, cast(order_status as string )order_status, CAST(FORMAT_TIMESTAMP(\'%Y-%m-%d %H:%M:%S\', PARSE_TIMESTAMP(\'%Y-%m-%dT%H:%M:%S%Ez\', purchase_date)) AS DATETIME) AS order_timestamp, IFNULL(SAFE_CAST(item_price AS FLOAT64), 0) AS pre_line_item_sales, IFNULL(SAFE_CAST(shipping_price AS FLOAT64), 0) AS pre_shipping_price, IFNULL(SAFE_CAST(quantity AS FLOAT64), 0) AS quantity, IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0) AS pre_tax, SAFE_DIVIDE(IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0), IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0) + IFNULL(SAFE_CAST(item_price AS FLOAT64), 0)) AS pre_tax_rate, IFNULL(safe_CAST(item_promotion_discount AS FLOAT64), 0) AS pre_discount, SAFE_DIVIDE(IFNULL(SAFE_CAST(item_promotion_discount AS FLOAT64), 0), (1 - (SAFE_DIVIDE(IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0), IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0) + IFNULL(SAFE_CAST(item_price AS FLOAT64), 0))) )) AS pre_discount_before_tax, NULL AS pre_gross_sales_after_tax, IFNULL(SAFE_CAST(item_price AS FLOAT64), 0) - (SAFE_DIVIDE(IFNULL(SAFE_CAST(item_promotion_discount AS FLOAT64), 0), (1 - (SAFE_DIVIDE(IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0), IFNULL(SAFE_CAST(item_tax AS FLOAT64), 0) + IFNULL(SAFE_CAST(item_price AS FLOAT64), 0))) ))) AS pre_gross_sales_before_tax, NULL AS pre_net_sales_before_tax, IFNULL(SAFE_CAST(item_price AS FLOAT64), 0) AS pre_total_sales, \'Amazon\' AS source, NULL AS landing_utm_medium, NULL AS landing_utm_source, NULL AS landing_utm_campaign, NULL AS referring_utm_medium, NULL AS referring_utm_source, NULL AS landing_utm_channel, NULL AS referring_utm_channel, NULL AS final_utm_channel, NULL AS new_customer_flag, NULL AS acquisition_channel, NULL AS acquisition_product, IFNULL(SAFE_CAST(shipping_tax AS FLOAT64), 0) AS pre_shipping_tax, IFNULL(SAFE_CAST(ship_promotion_discount AS FLOAT64), 0) AS pre_ship_promotion_discount, IFNULL(SAFE_CAST(gift_wrap_price AS FLOAT64), 0) AS pre_gift_wrap_price, IFNULL(SAFE_CAST(gift_wrap_tax AS FLOAT64), 0) AS pre_gift_wrap_tax, cast(null as string) AS Email, cast(null as string) AS Name, cast(null as string) as Recipient_Name FROM ( SELECT *, purchase_date AS Purchase_datetime_PDT FROM neshanka-wh.maplemonk.Custom_Amazon_Seller_Partner_Amazon_USA_GET_FLAT_FILE_ALL_ORDERS_DATA_BY_LAST_UPDATE_GENERAL ) X; CREATE OR REPLACE TABLE neshanka-wh.maplemonk.neshanka_wh_AMAZON_USA_FACT_ITEMS AS SELECT fi.*, IFNULL(PRE_line_item_sales, 0) * IFNULL(gr.Close, 85.0) AS line_item_sales, IFNULL(PRE_shipping_price, 0) * IFNULL(gr.Close, 85.0) AS shipping_price, IFNULL(PRE_tax, 0) * IFNULL(gr.Close, 85.0) AS tax, IFNULL(PRE_discount, 0) * IFNULL(gr.Close, 85.0) AS discount, IFNULL(PRE_discount_before_tax, 0) * IFNULL(gr.Close, 85.0) AS discount_before_tax, IFNULL(PRE_gross_sales_after_tax, 0) * IFNULL(gr.Close, 85.0) AS gross_sales_after_tax, IFNULL(PRE_gross_sales_before_tax, 0) * IFNULL(gr.Close, 85.0) AS gross_sales_before_tax, IFNULL(PRE_net_sales_before_tax, 0) * IFNULL(gr.Close, 85.0) AS net_sales_before_tax, IFNULL(PRE_total_sales, 0) * IFNULL(gr.Close, 85.0) AS total_sales, IFNULL(PRE_shipping_tax, 0) * IFNULL(gr.Close, 85.0) AS shipping_tax, IFNULL(PRE_ship_promotion_discount, 0) * IFNULL(gr.Close, 85.0) AS ship_promotion_discount, IFNULL(PRE_gift_wrap_price, 0) * IFNULL(gr.Close, 85.0) AS gift_wrap_price, IFNULL(PRE_gift_wrap_tax, 0) * IFNULL(gr.Close, 85.0) AS gift_wrap_tax, p.name AS product_name_final, COALESCE(UPPER(CAST(p.category AS STRING)), UPPER(CAST(fi.category AS STRING))) AS product_category, UPPER(CAST(p.sub_category AS STRING)) AS product_sub_category, p.commonsku, gr.Close AS conversion_rate FROM neshanka-wh.maplemonk.neshanka_wh_AMAZON_USA_FACT_ITEMS_INTERMEDIATE fi left join (select * from (select skucode, name, category, sub_category , null as commonsku , row_number()over (partition by skucode order by length(ifnull(skucode,\'\')) desc) rw from neshanka-wh.maplemonk.sku_master ) where rw = 1 ) p on lower(replace(fi.sku,\' \',\'\')) = lower(p.skucode) LEFT JOIN ( SELECT DATE(PARSE_TIMESTAMP(\'%m/%d/%Y %H:%M:%S\', Date)) AS rate_date, SAFE_CAST(Close AS FLOAT64) AS Close FROM Maplemonk.Google_sheet_USD_INR_Conversion_Rate ) gr ON DATE(fi.order_timestamp) = gr.rate_date ;",
                    "transaction": true
                }
            ) }}
